/**
 * Deterministic synthesis for the hip-hop one-shot bank (scripts/instruments/hiphop/build.ts).
 *
 * Every sound comes from a seed: kick bodies, snare noise, metallic hat clusters, 808 subs, chord
 * stabs, plucks, bells and vinyl textures. No recordings and no third-party audio are involved, so
 * the whole bank is owned outright and can be regenerated byte-for-byte.
 */

export const RATE = 44_100;
const TAU = Math.PI * 2;

export type Rng = () => number;

/** mulberry32: a small, fast PRNG so one seed always produces the same hit. */
export function rng(seed: number): Rng {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

const midiHz = (note: number): number => 440 * Math.pow(2, (note - 69) / 12);

function buf(seconds: number): Float32Array {
  return new Float32Array(Math.max(16, Math.round(seconds * RATE)));
}

function noise(r: Rng, frames: number): Float32Array {
  const out = new Float32Array(frames);
  for (let i = 0; i < frames; i++) out[i] = r() * 2 - 1;
  return out;
}

/**
 * Topology-preserving state-variable filter (Zavalishin). Unlike the naive Chamberlin form it stays
 * stable right up to Nyquist, which matters for the 7–9 kHz hat and cymbal bands.
 */
function svf(b: Float32Array, freq: number, q: number, mode: 'lp' | 'hp' | 'bp'): void {
  const fc = Math.min(RATE * 0.45, Math.max(20, freq));
  const g = Math.tan((Math.PI * fc) / RATE);
  const k = 1 / Math.max(0.35, q);
  const a1 = 1 / (1 + g * (g + k));
  const a2 = g * a1;
  const a3 = g * a2;
  let ic1 = 0;
  let ic2 = 0;
  for (let i = 0; i < b.length; i++) {
    const v0 = b[i];
    const v3 = v0 - ic2;
    const v1 = a1 * ic1 + a2 * v3;
    const v2 = ic2 + a2 * ic1 + a3 * v3;
    ic1 = 2 * v1 - ic1;
    ic2 = 2 * v2 - ic2;
    b[i] = mode === 'lp' ? v2 : mode === 'hp' ? v0 - k * v1 - v2 : v1;
  }
  for (let i = 0; i < b.length; i++) if (!Number.isFinite(b[i])) b[i] = 0;
}

function normalize(b: Float32Array, peak = 0.92): void {
  let max = 0;
  for (let i = 0; i < b.length; i++) {
    const v = b[i];
    if (!Number.isFinite(v)) b[i] = 0;
    else max = Math.max(max, Math.abs(v));
  }
  if (max < 1e-6) return;
  const gain = peak / max;
  for (let i = 0; i < b.length; i++) b[i] *= gain;
}

function fade(b: Float32Array, seconds = 0.005): void {
  const n = Math.min(b.length, Math.max(2, Math.round(seconds * RATE)));
  for (let i = 0; i < n; i++) b[b.length - 1 - i] *= i / n;
}

/** tanh-ish saturation that keeps a hit's body intact. */
function saturate(b: Float32Array, drive: number): void {
  if (drive <= 0) return;
  const k = 1 + drive * 6;
  const norm = Math.tanh(k);
  for (let i = 0; i < b.length; i++) b[i] = Math.tanh(b[i] * k) / norm;
}

/** Exponential decay, optionally with a short attack ramp. */
function decay(b: Float32Array, seconds: number, attack = 0.001): void {
  const atk = Math.max(1, Math.round(attack * RATE));
  for (let i = 0; i < b.length; i++) {
    const t = i / RATE;
    b[i] *= Math.min(1, i / atk) * Math.exp(-t / Math.max(0.004, seconds));
  }
}

/** Sine with an exponential pitch drop (kick bodies, 808s, toms). */
function sweep(b: Float32Array, from: number, to: number, pitchDecay: number, amp: number): void {
  let phase = 0;
  for (let i = 0; i < b.length; i++) {
    const t = i / RATE;
    const f = to + (from - to) * Math.exp(-t / Math.max(0.002, pitchDecay));
    phase += (TAU * f) / RATE;
    b[i] += Math.sin(phase) * amp;
  }
}

/** Inharmonic square cluster: the metallic core of hats, cymbals and cowbells. */
function metallic(r: Rng, frames: number, base: number, spread: number, partials = 6): Float32Array {
  const b = new Float32Array(frames);
  for (let p = 0; p < partials; p++) {
    const f = base * (1 + p * spread) * (0.92 + r() * 0.16);
    const amp = 0.5 / (1 + p * 0.7);
    let phase = r() * TAU;
    for (let i = 0; i < frames; i++) {
      phase += (TAU * f) / RATE;
      b[i] += (phase % TAU < Math.PI ? 1 : -1) * amp;
    }
  }
  return b;
}

// ---------------------------------------------------------------- drums

export function kick(seed: number): Float32Array {
  const r = rng(seed);
  const body = 0.26 + r() * 0.5;
  const b = buf(body + 0.06);
  const low = 39 + r() * 14;
  sweep(b, 95 + r() * 95, low, 0.026 + r() * 0.03, 0.95);
  const clickFrames = Math.round(0.014 * RATE);
  const click = noise(r, clickFrames);
  svf(click, 1600 + r() * 3600, 1.2, 'hp');
  const clickGain = 0.2 + r() * 0.45;
  for (let i = 0; i < click.length; i++) b[i] += click[i] * clickGain * Math.exp(-i / RATE / 0.0045);
  saturate(b, r() * 0.55);
  decay(b, body * 0.42 + 0.05);
  normalize(b, 0.95);
  fade(b);
  return b;
}

export function subHit(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.3 + r() * 0.9;
  const b = buf(len + 0.05);
  const low = 30 + r() * 22;
  sweep(b, low * 1.9, low, 0.045 + r() * 0.05, 0.95);
  saturate(b, r() * 0.35);
  decay(b, len * 0.55, 0.004);
  normalize(b, 0.95);
  fade(b, 0.012);
  return b;
}

export function snare(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.15 + r() * 0.32;
  const b = buf(len + 0.04);
  const tone = 165 + r() * 100;
  sweep(b, tone * 1.1, tone * 0.8, 0.045, 0.5);
  const n = noise(r, b.length);
  svf(n, 1300 + r() * 2400, 0.9, 'bp');
  svf(n, 220, 0.6, 'hp');
  const noiseGain = 0.5 + r() * 0.35;
  for (let i = 0; i < b.length; i++) b[i] += n[i] * noiseGain;
  saturate(b, r() * 0.3);
  decay(b, len * 0.38 + 0.03, 0.002);
  normalize(b, 0.9);
  fade(b);
  return b;
}

export function clap(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.2 + r() * 0.3;
  const b = buf(len + 0.06);
  const bursts = 3 + Math.floor(r() * 4);
  const spread = 0.007 + r() * 0.009;
  for (let k = 0; k < bursts; k++) {
    const at = Math.round(k * spread * RATE);
    const n = noise(r, Math.round((0.011 + r() * 0.01) * RATE));
    svf(n, 850 + r() * 950, 1.5, 'bp');
    svf(n, 520, 0.7, 'hp');
    for (let i = 0; i < n.length && at + i < b.length; i++) b[at + i] += n[i] * (0.5 + 0.14 * k);
  }
  const tail = noise(r, b.length);
  svf(tail, 1500 + r() * 1000, 0.7, 'bp');
  const tailStart = Math.round(0.028 * RATE);
  for (let i = tailStart; i < b.length; i++) b[i] += tail[i] * 0.22 * Math.exp(-(i - tailStart) / RATE / (len * 0.35));
  normalize(b, 0.9);
  fade(b);
  return b;
}

export function rim(seed: number): Float32Array {
  const r = rng(seed);
  const b = buf(0.085 + r() * 0.07);
  sweep(b, 1500 + r() * 1000, 650, 0.006, 0.5);
  const n = noise(r, b.length);
  svf(n, 2400 + r() * 1800, 2.4, 'bp');
  const gain = 0.45 + r() * 0.25;
  for (let i = 0; i < b.length; i++) b[i] += n[i] * gain;
  decay(b, 0.017 + r() * 0.022, 0.0005);
  normalize(b, 0.85);
  fade(b, 0.003);
  return b;
}

export function hat(seed: number, kind: 'closed' | 'open' | 'pedal'): Float32Array {
  const r = rng(seed);
  const len = kind === 'closed' ? 0.042 + r() * 0.06 : kind === 'pedal' ? 0.08 + r() * 0.08 : 0.3 + r() * 0.45;
  const b = metallic(r, buf(len + 0.05).length, 5000 + r() * 2900, 0.33);
  const n = noise(r, b.length);
  svf(n, 6200 + r() * 2800, 0.8, 'hp');
  for (let i = 0; i < b.length; i++) b[i] = b[i] * 0.55 + n[i] * 0.6;
  svf(b, 6800 + r() * 2200, 0.7, 'hp');
  decay(b, kind === 'open' ? len * 0.5 : len * 0.4, 0.0006);
  normalize(b, 0.75);
  fade(b, 0.006);
  return b;
}

export function cymbal(seed: number, ride: boolean): Float32Array {
  const r = rng(seed);
  const len = 0.55 + r() * 0.95;
  const b = metallic(r, buf(len + 0.08).length, ride ? 1350 + r() * 850 : 850 + r() * 950, 0.47, 7);
  const n = noise(r, b.length);
  svf(n, 4800, 0.8, 'hp');
  for (let i = 0; i < b.length; i++) b[i] = b[i] * 0.5 + n[i] * 0.4;
  decay(b, len * 0.45, 0.002);
  normalize(b, 0.65);
  fade(b, 0.02);
  return b;
}

// ---------------------------------------------------------------- percussion

export function shaker(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.07 + r() * 0.12;
  const b = noise(r, buf(len + 0.03).length);
  svf(b, 5200 + r() * 3200, 0.8, 'hp');
  decay(b, len * 0.42, 0.006 + r() * 0.006);
  normalize(b, 0.7);
  fade(b, 0.004);
  return b;
}

export function tambourine(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.09 + r() * 0.16;
  const b = metallic(r, buf(len + 0.04).length, 6200 + r() * 2600, 0.36, 7);
  const n = noise(r, b.length);
  svf(n, 7000, 0.8, 'hp');
  for (let i = 0; i < b.length; i++) b[i] = b[i] * 0.6 + n[i] * 0.35;
  decay(b, len * 0.45, 0.002);
  normalize(b, 0.7);
  fade(b, 0.006);
  return b;
}

export function cowbell(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.1 + r() * 0.2;
  const b = buf(len + 0.04);
  const f1 = 470 + r() * 160;
  const f2 = f1 * (1.45 + r() * 0.2);
  let p1 = 0;
  let p2 = 0;
  for (let i = 0; i < b.length; i++) {
    p1 += (TAU * f1) / RATE;
    p2 += (TAU * f2) / RATE;
    b[i] = ((p1 % TAU < Math.PI ? 1 : -1) * 0.5 + (p2 % TAU < Math.PI ? 1 : -1) * 0.3) * Math.exp(-i / RATE / (len * 0.5));
  }
  svf(b, 3200, 0.8, 'lp');
  normalize(b, 0.7);
  fade(b, 0.006);
  return b;
}

export function conga(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.16 + r() * 0.3;
  const b = buf(len + 0.04);
  const low = 150 + r() * 90;
  sweep(b, low * 1.5, low, 0.035, 0.85);
  const slap = noise(r, Math.round(0.02 * RATE));
  svf(slap, 1400 + r() * 1200, 1.1, 'bp');
  for (let i = 0; i < slap.length; i++) b[i] += slap[i] * 0.35 * Math.exp(-i / RATE / 0.006);
  decay(b, len * 0.5, 0.002);
  normalize(b, 0.85);
  fade(b);
  return b;
}

export function woodblock(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.05 + r() * 0.08;
  const b = buf(len + 0.03);
  sweep(b, 900 + r() * 700, 700 + r() * 400, 0.008, 0.7);
  const n = noise(r, b.length);
  svf(n, 1800 + r() * 1500, 2, 'bp');
  for (let i = 0; i < b.length; i++) b[i] += n[i] * 0.3;
  decay(b, 0.014 + r() * 0.02, 0.0006);
  normalize(b, 0.8);
  fade(b, 0.003);
  return b;
}

// ---------------------------------------------------------------- bass

export function bass808(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.4 + r() * 1.6;
  const b = buf(len + 0.06);
  const low = 31 + r() * 28;
  sweep(b, low * 2.5, low, 0.03 + r() * 0.05, 0.95);
  saturate(b, 0.15 + r() * 0.95);
  decay(b, len * 0.5, 0.004);
  normalize(b, 0.95);
  fade(b, 0.012);
  return b;
}

export function bassPluck(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.32 + r() * 0.85;
  const b = buf(len + 0.05);
  const f = 44 + r() * 58;
  let phase = 0;
  for (let i = 0; i < b.length; i++) {
    phase += f / RATE;
    if (phase >= 1) phase -= 1;
    b[i] = (phase * 2 - 1) * 0.6 + Math.sin(TAU * phase) * 0.55;
  }
  svf(b, 380 + r() * 1500, 0.95, 'lp');
  saturate(b, 0.1 + r() * 0.35);
  decay(b, len * 0.38, 0.003);
  normalize(b, 0.9);
  fade(b);
  return b;
}

// ---------------------------------------------------------------- keys, plucks, bells

const SHAPES: readonly (readonly number[])[] = [
  [0, 3, 7, 10],
  [0, 4, 7, 11],
  [0, 5, 7, 10],
  [0, 3, 7, 14],
  [0, 7, 12, 15],
  [0, 3, 10],
  [0, 4, 7],
];

export function chordHit(seed: number, stab: boolean): Float32Array {
  const r = rng(seed);
  const len = stab ? 0.1 + r() * 0.16 : 0.45 + r() * 0.95;
  const root = 45 + Math.floor(r() * 12);
  const shape = SHAPES[Math.floor(r() * SHAPES.length)];
  const b = buf(len + 0.05);
  for (const semi of shape) {
    const f = midiHz(root + semi) * (1 + (r() - 0.5) * 0.005);
    let phase = r() * TAU;
    for (let i = 0; i < b.length; i++) {
      phase += (TAU * f) / RATE;
      b[i] += Math.sin(phase) * 0.3 + ((phase / TAU) % 1) * 2 - 1;
    }
  }
  svf(b, 800 + r() * 2800, 0.9, 'lp');
  saturate(b, r() * 0.25);
  decay(b, len * (stab ? 0.28 : 0.5), 0.003);
  normalize(b, 0.82);
  fade(b);
  return b;
}

export function pluck(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.35 + r() * 0.8;
  const f = 110 + r() * 340;
  const b = buf(len + 0.03);
  const n = Math.max(4, Math.round(RATE / f));
  const line = noise(r, n);
  const damping = 0.496 + r() * 0.0025;
  let idx = 0;
  for (let i = 0; i < b.length; i++) {
    const v = line[idx];
    const next = line[(idx + 1) % n];
    line[idx] = (v + next) * damping;
    b[i] = v;
    idx = (idx + 1) % n;
  }
  svf(b, 3200 + r() * 2400, 0.8, 'lp');
  decay(b, len * 0.55, 0.002);
  normalize(b, 0.85);
  fade(b);
  return b;
}

export function bell(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.6 + r() * 1.0;
  const f = midiHz(72 + Math.floor(r() * 24));
  const ratio = 1.4 + r() * 2.6;
  const index = 1.4 + r() * 4;
  const b = buf(len + 0.05);
  for (let i = 0; i < b.length; i++) {
    const t = i / RATE;
    const mod = Math.sin(TAU * f * ratio * t) * index * Math.exp(-t / (len * 0.25));
    b[i] = Math.sin(TAU * f * t + mod) * Math.exp(-t / (len * 0.4));
  }
  normalize(b, 0.8);
  fade(b);
  return b;
}

export function texture(seed: number): Float32Array {
  const r = rng(seed);
  const len = 0.8 + r() * 1.2;
  const b = buf(len);
  const kind = Math.floor(r() * 3);
  if (kind === 0) {
    // vinyl: hiss plus sparse crackles
    for (let i = 0; i < b.length; i++) b[i] = (r() * 2 - 1) * 0.08;
    const crackles = 30 + Math.floor(r() * 90);
    for (let c = 0; c < crackles; c++) {
      const at = Math.floor(r() * b.length);
      const amp = 0.25 + r() * 0.7;
      const frames = Math.round((0.0008 + r() * 0.003) * RATE);
      for (let i = 0; i < frames && at + i < b.length; i++) b[at + i] += amp * Math.exp(-i / (frames * 0.35)) * (r() * 2 - 1);
    }
    svf(b, 2800, 0.8, 'hp');
  } else if (kind === 1) {
    // tape hiss
    for (let i = 0; i < b.length; i++) b[i] = (r() * 2 - 1) * 0.2;
    svf(b, 2400, 0.7, 'hp');
    svf(b, 9000, 0.7, 'lp');
  } else {
    // air / noise swell
    for (let i = 0; i < b.length; i++) b[i] = (r() * 2 - 1) * 0.5;
    svf(b, 1200 + r() * 1800, 0.6, 'bp');
    const atk = Math.round(b.length * 0.5);
    for (let i = 0; i < b.length; i++) {
      if (i < atk) b[i] *= Math.sin((i / atk) * (Math.PI / 2));
      else b[i] *= Math.exp(-(i - atk) / RATE / (len * 0.3));
    }
  }
  normalize(b, 0.6);
  fade(b, 0.02);
  return b;
}
